import{_ as a,o as s,c as e,a2 as t}from"./chunks/framework.DLjqJywH.js";const c=JSON.parse('{"title":"使用 AI 接入 xapiforge","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/ai-integration.md","filePath":"getting-started/ai-integration.md","lastUpdated":1786148643000}'),l={name:"getting-started/ai-integration.md"};function n(p,i,h,o,r,d){return s(),e("div",null,[...i[0]||(i[0]=[t(`<h1 id="使用-ai-接入-xapiforge" tabindex="-1">使用 AI 接入 xapiforge <a class="header-anchor" href="#使用-ai-接入-xapiforge" aria-label="Permalink to &quot;使用 AI 接入 xapiforge&quot;">​</a></h1><p>仓库提供 <code>xapiforge-integration</code> Skill，供使用 Codex 或其他支持 <code>SKILL.md</code> 的 AI 编程工具接入项目。它会要求 AI 先检查接入项目，再选择 adapter、生成客户端并完成验证，不会把示例端口、OAuth 字段或业务协议直接复制到项目中。</p><p>Skill 源文件位于：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.agents/skills/xapiforge-integration/</span></span></code></pre></div><h2 id="安装到-codex" tabindex="-1">安装到 Codex <a class="header-anchor" href="#安装到-codex" aria-label="Permalink to &quot;安装到 Codex&quot;">​</a></h2><p>克隆 xapiforge 仓库后执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CODEX_HOME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}/skills&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .agents/skills/xapiforge-integration</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CODEX_HOME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}/skills/&quot;</span></span></code></pre></div><p>重新开始一个 Codex 任务，让 Codex 重新发现 Skill。其他 AI 编程工具如果支持 Skills，按该工具规定的 Skill 目录安装同一文件夹；不要只复制 <code>SKILL.md</code>，项目检查脚本和 references 也是 Skill 的一部分。</p><h2 id="调用方式" tabindex="-1">调用方式 <a class="header-anchor" href="#调用方式" aria-label="Permalink to &quot;调用方式&quot;">​</a></h2><p>在接入项目目录中明确调用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>使用 $xapiforge-integration 检查当前项目，选择正确的 adapter，</span></span>
<span class="line"><span>接入现有 OpenAPI，并完成类型检查、生产构建和一个真实或 mock 请求验证。</span></span></code></pre></div><p>也可以给出已有约束：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>使用 $xapiforge-integration 接入这个 Capacitor 项目。</span></span>
<span class="line"><span>沿用现有 pnpm、AuthService 和离线 swagger，不要改登录协议。</span></span></code></pre></div><p>Skill 会读取项目锁文件、依赖、配置、OpenAPI 文件和现有 API/Auth 代码。它不会读取不到后端协议时自行编造；缺少 OpenAPI 地址、base URL 或刷新协议时，会要求接入者提供。</p><p>多后端或非规范 Swagger 项目还应要求 AI 逐 service 记录来源、运行时地址和已确认的不规范形态，并按<a href="./multi-backend">多后端与非规范 OpenAPI 接入</a>区分 hook、runtime middleware 和后端修复。不要接受“生成成功”作为唯一验收证据。</p><h2 id="ai-应该交付什么" tabindex="-1">AI 应该交付什么 <a class="header-anchor" href="#ai-应该交付什么" aria-label="Permalink to &quot;AI 应该交付什么&quot;">​</a></h2><p>一次完成的接入至少应说明：</p><ul><li>安装了哪些包，为什么选择该 adapter；</li><li><code>xapiforge.config.ts</code> 对应哪个真实项目和服务；</li><li>生成了哪些客户端文件；</li><li><code>AuthService</code> 和 TokenStore 接到了哪里；</li><li>哪些类型检查、测试和生产构建已经通过；</li><li>实际观察了哪个真实或 mock 请求；</li><li>哪些设备、凭据、CORS、证书或后端条件尚未验证。</li></ul><p>只完成依赖安装或代码生成，不算接入完成。</p><h2 id="更新-skill" tabindex="-1">更新 Skill <a class="header-anchor" href="#更新-skill" aria-label="Permalink to &quot;更新 Skill&quot;">​</a></h2><p>Skill 随 xapiforge 仓库维护。更新前先查看 Skill 目录的改动，再用新目录替换本地安装版本。Skill 的详细步骤应与当前发布版本匹配；接入旧版 npm 包时，让 AI 优先检查已安装包的实际导出，不要直接套用最新文档。</p>`,21)])])}const g=a(l,[["render",n]]);export{c as __pageData,g as default};
